/// <summary>
/// Extension of form AgreementClassification
/// CB_202 SalesQuota changes by Akshay
/// </summary>
[ExtensionOf(formStr(AgreementClassification))]
final class METAgreementClassification_Extension
{
}

Method.Source:
    /// <summary>
    /// Updates the visibility of control on the <c>AgreementClassification</c> form.
    /// </summary>
    void updateDesign()
    {
        next updateDesign();

        boolean         calledForSalesAgreement = agreementRelationTypeToUse == tablenum(SalesAgreementHeader);
        FormDataSource  dataSource = AgreementClassification_ds;
        FormDataObject  metCustReasonObject = dataSource.object(fieldName2id(dataSource.table(), formDataFieldStr(AgreementClassification, AgreementClassification, METCustReason)));

        metCustReasonObject.visible(calledForSalesAgreement);
        metCustReasonObject.mandatory(calledForSalesAgreement);
        
    }
